      {slug:'figures-table',title:'Match the figures to a table',prompt:'Count the counters in each figure. Build the next figure in the table.',type:'sequence',kind:'number',values:range(big?5:2,big?5:2,5),given:[0],table:{heading:big?'Term number':'Figure number',row:'Counters',positions:range(1,1,5)},figureCounts:range(big?5:2,big?5:2,4),playMode:'figures-table',fields:[choice('change','How many counters join each time?',big?['2 more','3 more','5 more']:['1 more','2 more','4 more'],big?'5 more':'2 more')],codes:big?['C1.2','C1.3','C1.4']:['C1.2','C1.3'],goal:big?'I can translate growing figures into a table of values.':'I can connect a growing shape pattern to its numbers.'},
      {slug:'next-three',title:'Find the next three shapes',prompt:'Look for the repeating core. Add the next three shapes.',type:'sequence',kind:'shape',tokens:{star:tokens.star,diamond:tokens.diamond,heart:tokens.heart},values:Array.from({length:15},(_,i)=>['star','star','diamond','heart','heart'][i%5]),given:range(0,1,12),coreAnswer:5,playMode:'next-three',codes:['C1.1','C1.3'],goal:'I can extend a repeating pattern and find its smallest core.'},
      {slug:'hops-table',title:'From hops to a table',prompt:`Start at ${32*scale}. Add ${3*scale} each time. Fill the trail and table.`,type:'sequence',kind:'number',values:range(32*scale,3*scale,8),given:[0,1,2],hop:3*scale,table:{heading:big?'Term number':'Step number',row:'Value',positions:range(1,1,8)},playMode:'hops-table',fields:[choice('predict',`What comes after ${53*scale}?`,[String(54*scale),String(56*scale),String(59*scale)],String(56*scale))],codes:big?['C1.2','C1.3','C1.4']:['C1.3','C1.4'],goal:'I can show one number pattern with hops and a table.'}
